document.addEventListener("DOMContentLoaded", function () {
  selectYearFilter();
  displayYearFilters();

  function selectYearFilter() {
    const yearFilters = document.querySelectorAll(
      '.year-filters input[type="radio"]'
    );
    yearFilters.forEach(function (filter) {
      filter.addEventListener("change", function () {
        yearFilters.forEach(function (f) {
          f.parentElement.classList.remove("selected");
        });
        filter.parentElement.classList.add("selected");
      });
    });

    const defaultSelected = document.querySelector(
      '.year-filters input[type="radio"]:checked'
    );
    if (defaultSelected) {
      defaultSelected.parentElement.classList.add("selected");
    }
  }

  function displayYearFilters() {
    const datesButton = document.querySelector(".filter-title");
    const yearFilterWrapper = document.querySelector('.year-filters');

    datesButton.addEventListener('click', function() {
      yearFilterWrapper.classList.toggle('active');
    });

  }

  jQuery(".slick-slider").slick({
    slidesToShow: 10,
    slidesToScroll: 5,
    centerMode: false,
    variableWidth: true,

    responsive: [
      {
        breakpoint: 1024,
        settings: {
          slidesToShow: 6,
          slidesToScroll: 3,
        },
      },
      {
        breakpoint: 600,
        settings: {
          slidesToShow: 3,
          slidesToScroll: 3,
        },
      },
    ],
  });
});
